def pre(n):
    """Precondition: n is in the valid input range."""
    return 2 <= n <= 120


def post(n, result):
    """Postcondition: result is the largest proper divisor of n."""

    # result must satisfy 1 <= result < n
    if result < 1 or result >= n:
        return False

    # result must divide n exactly
    if n % result != 0:
        return False

    # result must be the *largest* divisor less than n
    # (no divisor strictly greater than result and strictly less than n)
    for d in range(result + 1, n):
        if n % d == 0:
            return False

    return True
